using Eto.Forms; using Rhino.UI;
namespace RhinoContextAssist;
internal sealed class ContextAssistOptionsPage:OptionsDialogPage
{
    readonly ContextAssistSettings _settings; ContextAssistOptionsControl? _control;
    public ContextAssistOptionsPage(ContextAssistSettings settings):base("Context Assist")=>_settings=settings;
    public override object PageControl=>_control??=new ContextAssistOptionsControl(_settings);
    public override bool ShowApplyButton=>true; public override bool ShowDefaultsButton=>false;
    public override bool OnApply(){_control?.ApplySettings();return true;}
}
internal sealed class ContextAssistOptionsControl:Panel
{
    readonly ContextAssistSettings _settings; readonly CheckBox _enabled=new(){Text="Context Assist aktivieren"}; readonly CheckBox _auto=new(){Text="Automatisch nach Nutzung priorisieren"}; readonly DropDown _position=new(); readonly NumericStepper _count=new(){MinValue=1,MaxValue=5,DecimalPlaces=0}; readonly DropDown _kind=new(); readonly ListBox _actions=new(); readonly CheckBox _actionEnabled=new(){Text="Aktion aktiviert"}; readonly CheckBox _favorite=new(){Text="Favorit (★)"}; readonly Label _usage=new(); List<ActionPreference> _current=new(); bool _updating;
    public ContextAssistOptionsControl(ContextAssistSettings s){_settings=s;_position.Items.Add("Neben Mauszeiger");_position.Items.Add("Neben Geometrie");foreach(var k in ActionCatalog.ConfigurableKinds)_kind.Items.Add(Name(k));var up=new Button{Text="Nach oben"};var down=new Button{Text="Nach unten"};var reset=new Button{Text="Nutzungsstatistik zurücksetzen"};up.Click+=(_,_)=>Move(-1);down.Click+=(_,_)=>Move(1);reset.Click+=(_,_)=>{_settings.ResetUsage();LoadAction();};_kind.SelectedIndexChanged+=(_,_)=>LoadKind();_actions.SelectedIndexChanged+=(_,_)=>LoadAction();_actionEnabled.CheckedChanged+=(_,_)=>Edit();_favorite.CheckedChanged+=(_,_)=>Edit();var layout=new DynamicLayout{Padding=10,Spacing=new Eto.Drawing.Size(6,6)};layout.AddRow(_enabled);layout.AddRow(_auto);layout.AddRow(new Label{Text="Position"},_position);layout.AddRow(new Label{Text="Anzahl Hauptaktionen"},_count);layout.AddRow(new Label{Text="Objekttyp"},_kind);layout.AddRow(_actions);layout.AddRow(_actionEnabled,_favorite);layout.AddRow(_usage);layout.AddRow(up,down);layout.AddRow(reset);Content=layout;LoadSettings();}
    void LoadSettings(){_updating=true;_enabled.Checked=_settings.Enabled;_auto.Checked=_settings.AutomaticPrioritization;_position.SelectedIndex=(int)_settings.PositionMode;_count.Value=_settings.PrimaryCount;_kind.SelectedIndex=0;_updating=false;LoadKind();}
    void LoadKind(){if(_kind.SelectedIndex<0)return;var k=ActionCatalog.ConfigurableKinds[_kind.SelectedIndex];_current=_settings.Preferences[k].Select(x=>new ActionPreference(x.Id,x.Enabled,x.Favorite)).ToList();Refresh();}
    void Refresh(){if(_kind.SelectedIndex<0)return;var k=ActionCatalog.ConfigurableKinds[_kind.SelectedIndex];var map=ActionCatalog.Defaults(k).ToDictionary(x=>x.Id);var keep=_actions.SelectedIndex;_updating=true;_actions.Items.Clear();foreach(var p in _current)if(map.TryGetValue(p.Id,out var a))_actions.Items.Add($"{a.Icon} {(p.Favorite?"★ ":"")}{(p.Enabled?"☑":"☐")} {a.Label}  ({_settings.UsageCount(p.Id)}×)");if(_current.Count>0)_actions.SelectedIndex=Math.Clamp(keep,0,_current.Count-1);_updating=false;LoadAction();}
    void LoadAction(){var i=_actions.SelectedIndex;if(i<0||i>=_current.Count)return;_updating=true;_actionEnabled.Checked=_current[i].Enabled;_favorite.Checked=_current[i].Favorite;_usage.Text=$"Verwendet: {_settings.UsageCount(_current[i].Id)}×";_updating=false;}
    void Edit(){if(_updating)return;var i=_actions.SelectedIndex;if(i<0||i>=_current.Count)return;_current[i]=_current[i] with{Enabled=_actionEnabled.Checked==true,Favorite=_favorite.Checked==true};SaveKind();Refresh();}
    void Move(int d){var i=_actions.SelectedIndex;var j=i+d;if(i<0||j<0||j>=_current.Count)return;(_current[i],_current[j])=(_current[j],_current[i]);SaveKind();Refresh();_actions.SelectedIndex=j;}
    void SaveKind(){if(_kind.SelectedIndex<0)return;var k=ActionCatalog.ConfigurableKinds[_kind.SelectedIndex];_settings.Preferences[k]=_current.Select(x=>new ActionPreference(x.Id,x.Enabled,x.Favorite)).ToList();}
    public void ApplySettings(){SaveKind();_settings.Enabled=_enabled.Checked==true;_settings.AutomaticPrioritization=_auto.Checked==true;_settings.PositionMode=(PopupPositionMode)Math.Max(0,_position.SelectedIndex);_settings.PrimaryCount=(int)_count.Value;_settings.Save();}
    static string Name(SelectionKind k)=>k switch{SelectionKind.PlanarBrepFace=>"Planare Teilfläche",SelectionKind.BrepFace=>"Teilfläche",SelectionKind.BrepEdge=>"Brep-Kante",SelectionKind.ClosedPlanarCurve=>"Geschlossene planare Kurve",SelectionKind.Curve=>"Kurve",SelectionKind.PlanarSurface=>"Planare Fläche",SelectionKind.Surface=>"Fläche",SelectionKind.SolidBrep=>"Geschlossener Körper",SelectionKind.Brep=>"Flächenverband",SelectionKind.Mesh=>"Mesh",SelectionKind.MeshFace=>"Mesh-Fläche",SelectionKind.MeshEdge=>"Mesh-Kante",SelectionKind.MeshVertex=>"Mesh-Vertex",SelectionKind.SubD=>"SubD",SelectionKind.SubDFace=>"SubD-Fläche",SelectionKind.SubDEdge=>"SubD-Kante",SelectionKind.SubDVertex=>"SubD-Vertex",SelectionKind.Multiple=>"Mehrfachauswahl",SelectionKind.Mixed=>"Gemischte Auswahl",_=>k.ToString()};
}
